 notes(('HIV/AIDS, addictive drugs, harmful traditional practices and drought are big problems we can fight with knowledge and action.','ኤች አይ ቪ/ኤድስ፣ ሱስ አምጪ ዕፆች፣ ጎጂ ልማዳዊ ድርጊቶችና ድርቅ በእውቀትና በተግባር ልንዋጋቸው የምንችላቸው ትልልቅ ችግሮች ናቸው።'),
  [('HIV: blood, unsafe sex, sharp tools, mother to child — not by touch.','ኤች አይ ቪ፦ ደም፣ ጥንቃቄ የጎደለው ግንኙነት፣ ስለታም መሣሪያ፣ ከእናት ወደ ልጅ — በንክኪ አይደለም።'),('Say no to chat, alcohol, cigarettes and shisha.','ለጫት፣ ለአልኮል፣ ለሲጋራና ለሺሻ እምቢ በሉ።'),('Stop early marriage, FGM and abduction.','ያለዕድሜ ጋብቻን፣ ግርዛትንና ጠለፋን አስቁሙ።'),('Drought → famine; prepare with water, trees and storage.','ድርቅ → ርሃብ፤ በውኃ፣ በዛፍና በክምችት ተዘጋጁ።')],
  [('ሱስ','addiction','መተው ያቃተ ልማድ'),('ጎጂ ልማዳዊ ድርጊት','harmful traditional practice','ጉዳት የሚያደርስ ልማድ'),('ድርቅ','drought','የዝናብ እጥረት')],('Know the facts, say no, speak up!','እውነቱን እወቁ፣ እምቢ በሉ፣ ድምፃችሁን አሰሙ!'),
  [(('Name 2 ways HIV does NOT spread','ኤች አይ ቪ የማይተላለፍባቸውን 2 መንገዶች ጥቀሱ'),('hugging, sharing food','መተቃቀፍ፣ ምግብ መጋራት')),(('One way to prepare for drought','ለድርቅ መዘጋጃ አንድ መንገድ'),('water harvesting','ውኃ ማቆር'))],
  (('Health club drama','የጤና ክበብ ድራማ'),('Health educators use drama to change behaviour. Create a short drama about saying no to drugs or early marriage.','የጤና አስተማሪዎች ባሕርይን ለመለወጥ ድራማ ይጠቀማሉ። ለዕፅ ወይም ለያለዕድሜ ጋብቻ እምቢ ስለማለት አጭር ድራማ አዘጋጁ።'),[('Choose one issue.','አንድ ጉዳይ ምረጡ።'),('Write a 3-scene story with a good ending.','መልካም ፍጻሜ ያለው ባለ3 ትዕይንት ታሪክ ጻፉ።'),('Include true facts from this chapter.','ከዚህ ምዕራፍ እውነተኛ መረጃዎችን አካትቱ።'),('Perform it at a school event.','በትምህርት ቤት ዝግጅት አቅርቡት።')])),
